import {createHash} from 'node:crypto';
export const A='11111111-1111-4111-8111-111111111111',B='22222222-2222-4222-8222-222222222222',C='33333333-3333-4333-8333-333333333333';
export const gameEntry='aaaaaaaaaaaaaaaaaaaaaaaa',iosEntry='bbbbbbbbbbbbbbbbbbbbbbbb';
export class CommonCloud {
  tables:Record<string,any[]>={};aliases=new Map<string,string>();queries:Array<{table:string;select:string}>=[];error:any=null;beforePublish:(()=>void)|null=null;
  // Round-trip accounting: every awaited from()/rpc() is one round trip; `waves` counts sequential depth (calls that start
  // while another is in flight share a wave). `latency` (ms) delays answers so concurrent calls overlap observably.
  roundTrips=0;waves=0;inFlight=0;latency=0;rejectJsonFilters=false;calls:Array<{kind:'from'|'rpc';name:string;select?:string;inSizes?:number[];filters?:string[]}>=[];
  // Isolates the service's module-level caches per fake cloud even when tests share one scope string.
  commonMemoryCachePartition=crypto.randomUUID();
  resetCounts(){this.roundTrips=0;this.waves=0;this.calls=[];this.queries=[];}
  /** Alias rows as the database sees them: the table plus legacy `aliases.set()` shortcuts. */
  aliasRows(){const rows=[...this.tables.portmgr_project_memory_aliases!];for(const [alias_memory_id,canonical_memory_id] of this.aliases)if(!rows.some(r=>r.alias_memory_id===alias_memory_id))rows.push({alias_memory_id,canonical_memory_id});return rows;}
  /** Same walk as public.portmgr_resolve_project_memory_id (schemaSql.ts); tests/common-memory-batching proves it against PGlite. */
  resolve(id:any){let current=id;if(current===null||current===undefined||String(current).trim()==='')return {data:current,error:null};for(let depth=0;depth<20;depth++){const next=this.aliasRows().find(r=>r.alias_memory_id===current)?.canonical_memory_id;if(next===undefined||next===null)return {data:current,error:null};if(next===current)return {data:null,error:{code:'P0001',message:'PROJECT_MEMORY_ALIAS_CYCLE'}};current=next;}return {data:null,error:{code:'P0001',message:'PROJECT_MEMORY_ALIAS_CHAIN_TOO_DEEP'}};}
  answer(signal:AbortSignal|undefined,compute:()=>any){if(this.inFlight===0)this.waves++;this.inFlight++;this.roundTrips++;const delay=this.latency>0?new Promise(r=>setTimeout(r,this.latency)):Promise.resolve();return delay.then(()=>signal?.aborted?{data:null,error:{name:'AbortError',message:'This operation was aborted',code:''}}:compute()).finally(()=>{this.inFlight--;});}
  constructor(){for(const name of ['common_memories','common_memory_operations','common_memory_revisions','common_memory_applications','common_memory_bindings','project_memory_trash','project_memory_heads','project_memory_revisions','project_memory_aliases','project_memory_labels'])this.tables['portmgr_'+name]=[];this.source(A,'### 물리\n<!-- memory-entry-id:cccccccccccccccccccccccc -->\n운전게임 물리 충돌 검증');this.source(B,`### 게임 조작\n<!-- memory-entry-id:${gameEntry} -->\n운전게임 조작은 시간에 독립적이어야 한다.\n\n### iOS 생명주기\n<!-- memory-entry-id:${iosEntry} -->\nSwiftUI 아이폰 앱은 백그라운드 복귀 연결을 확인한다.`);this.source(C,'### iOS 권한\n<!-- memory-entry-id:dddddddddddddddddddddddd -->\n아이폰 권한은 사용자 동의로 시작한다.');}
  source(memoryId:string,body:string){const content='# Memory\n\n## Decisions\n\n'+body+'\n',id=crypto.randomUUID();this.tables.portmgr_project_memory_revisions!.push({id,memory_id:memoryId,project_name:({[A]:'원본 A',[B]:'원본 B',[C]:'원본 C'} as any)[memoryId]??memoryId,github_url:'https://github.com/example/'+memoryId,content,content_hash:createHash('sha256').update(content).digest('hex')});this.tables.portmgr_project_memory_heads=this.tables.portmgr_project_memory_heads!.filter(r=>r.memory_id!==memoryId);this.tables.portmgr_project_memory_heads.push({memory_id:memoryId,head_revision_id:id});return id;}
  from(table:string){const self=this;let ins:Array<[string,unknown[]]>=[];let cols='*',eqs:Array<[string,unknown]>=[],json:Array<[string,string,any]>=[],single=false,optional=false,limit=Infinity,start=0,end=Infinity,sortKey='',descending=false,insert:any=null,signal:AbortSignal|undefined;
    const pick=(row:any,expression:string)=>{const path=expression.split(/->>?/);let value:any=row[path.shift()!];for(const part of path)value=value?.[part];if(expression.includes('->>')&&value!==null&&value!==undefined)value=String(value);return value;};
    const contains=(a:any,b:any):boolean=>Array.isArray(b)?Array.isArray(a)&&b.every(x=>a.some(y=>contains(y,x))):b&&typeof b==='object'?!!a&&typeof a==='object'&&!Array.isArray(a)&&Object.keys(b).every(k=>contains(a[k],b[k])):a===b;
    const q:any={in(k:string,v:unknown[]){ins.push([k,v]);return q;},select(v:string){cols=v;self.queries.push({table,select:v});return q;},eq(k:string,v:unknown){eqs.push([k,v]);return q;},
      filter(k:string,op:string,v:any){json.push([k,op,v]);return q;},not(k:string,op:string,v:any){json.push([k,'not.'+op,v]);return q;},
      single(){single=true;return q;},maybeSingle(){single=true;optional=true;return q;},range(a:number,b:number){start=a;end=b;return q;},limit(n:number){limit=n;return q;},order(k:string,o:any={}){sortKey=k;descending=o.ascending===false;return q;},insert(v:any){insert=v;return q;},abortSignal(v?:AbortSignal){signal=v;return q;},then(ok:any,no:any){self.calls.push({kind:'from',name:table,select:cols,inSizes:ins.map(([,v])=>v.length),filters:json.map(([k,op,v])=>`${k}=${op}.${typeof v==='string'?v:JSON.stringify(v)}`)});return self.answer(signal,()=>{if(self.error)return {data:null,error:self.error};const rows=table==='portmgr_project_memory_aliases'?self.aliasRows():self.tables[table];if(!rows)return {data:null,error:{code:'PGRST205'}};if(self.rejectJsonFilters&&json.some(([,op])=>op==='cs'))return {data:null,error:{code:'PGRST100',message:'failed to parse filter'}};if(insert){if(rows.some(r=>r.application_id===insert.application_id))return {data:null,error:{code:'23505'}};rows.push({...structuredClone(insert),created_at:new Date().toISOString()});return {data:null,error:null};}
      const jsonOk=(r:any)=>json.every(([k,op,v])=>{const value=pick(r,k);if(op==='cs')return contains(value,typeof v==='string'?JSON.parse(v):v);if(op==='not.is')return value!==null&&value!==undefined;throw Error('fake cloud: unsupported filter '+op);});
      let found=rows.filter(r=>eqs.every(([k,v])=>r[k]===v)&&ins.every(([k,v])=>v.includes(r[k]))&&jsonOk(r));if(sortKey)found.sort((a,b)=>String(a[sortKey]).localeCompare(String(b[sortKey]))*(descending?-1:1));found=found.slice(start,Math.min(end+1,start+limit));const project=(row:any)=>cols==='*'?structuredClone(row):Object.fromEntries(cols.split(',').map(c=>{const [alias,expression]=c.includes(':')?c.split(':'):[c,c];return [alias,structuredClone(pick(row,expression!))];}));return {data:single?(found[0]?project(found[0]):null):found.map(project),error:single&&!optional&&!found.length?{code:'PGRST116'}:null};}).then(ok,no);}};return q;
  }
  rpc(name:string,p:any){let signal:AbortSignal|undefined;const q:any={abortSignal(v?:AbortSignal){signal=v;return q;},then:(ok:any,no:any)=>{this.calls.push({kind:'rpc',name});return this.answer(signal,()=>{if(this.error)return {data:null,error:this.error};if(name==='portmgr_resolve_project_memory_id')return this.resolve(p.p_memory_id);
    if(name==='portmgr_list_project_memory_head_page')return {data:this.tables.portmgr_project_memory_heads!.filter(h=>!p.p_after_memory_id||h.memory_id>p.p_after_memory_id).sort((a,b)=>a.memory_id.localeCompare(b.memory_id)).slice(0,p.p_limit).map(h=>this.tables.portmgr_project_memory_revisions!.find(r=>r.id===h.head_revision_id)),error:null};
    if(name==='portmgr_bind_common_memory'){const old=this.tables.portmgr_common_memory_bindings!.find(r=>r.project_memory_id===p.p_memory_id);if((old?.version??0)!==p.p_expected_version)return {error:{message:'COMMON_MEMORY_VERSION_CHANGED'},data:null};const row={project_memory_id:p.p_memory_id,version:p.p_expected_version+1,project_goal:p.p_project_goal,selections:p.p_selections};if(old)Object.assign(old,row);else this.tables.portmgr_common_memory_bindings!.push(row);return {data:{version:row.version},error:null};}
    if(name!=='portmgr_write_common_memory')throw Error('unknown RPC '+name);
    const groups=this.tables.portmgr_common_memories!,old=groups.find(r=>r.group_id===p.p_group_id),receipt=this.tables.portmgr_common_memory_operations!.find(r=>r.group_id===p.p_group_id&&r.request_id===p.p_request_id);
    if(receipt)return receipt.request_hash===p.p_request_hash?{data:{state:old.state,version:old.version,replayed:true,committedVersion:receipt.result.version},error:null}:{data:null,error:{message:'COMMON_MEMORY_REQUEST_CONFLICT'}};
    if((old?.version??0)!==p.p_expected_version)return {data:null,error:{message:'COMMON_MEMORY_VERSION_CHANGED'}};
    const state=structuredClone(p.p_state),pub=state.publication;
    if(pub&&pub.id!==old?.state.publication?.id){this.beforePublish?.();for(const h of pub.sourceHeads){const head=this.tables.portmgr_project_memory_heads!.find(r=>r.memory_id===h.memoryId),rev=this.tables.portmgr_project_memory_revisions!.find(r=>r.id===head?.head_revision_id);if(rev?.id!==h.revisionId||rev.content_hash!==h.contentHash)return {data:null,error:{message:'COMMON_MEMORY_SOURCE_CHANGED'}};}this.tables.portmgr_common_memory_revisions!.push({group_id:state.id,revision_id:pub.id,payload:pub,created_at:new Date().toISOString()});}
    const row={group_id:state.id,state,version:p.p_expected_version+1};if(old)Object.assign(old,row);else groups.push(row);this.tables.portmgr_common_memory_operations!.push({group_id:state.id,request_id:p.p_request_id,request_hash:p.p_request_hash,result:{version:row.version}});return {data:{state,version:row.version},error:null};}).then(ok,no);}};return q;}
}
